import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    s = list(data[1])

    if n % 2 != 0:
        print(":(")
        return

    balance = 0
    q_count = 0

    for char in s:
        if char == '?':
            q_count += 1
        elif char == '(':
            balance += 1
        else:
            balance -= 1

    if balance > n // 2:
        print(":(")
        return

    needed_open = n // 2 - balance
    open_slots = 0

    for i in range(n):
        if s[i] == '?':
            if open_slots < needed_open:
                s[i] = '('
                open_slots += 1
            else:
                s[i] = ')'

    result = ''.join(s)

    if result[0] == ')' or result[-1] == '(':
        print(":(")
        return

    bal = 0
    for i, char in enumerate(result):
        if char == '(':
            bal += 1
        else:
            bal -= 1
        if bal < 0:
            print(":(")
            return
        if i < n - 1 and bal == 0:
            print(":(")
            return

    if bal != 0:
        print(":(")
        return

    print(result)

solve()
